def _available():
    return True   # weights are embedded


def _melfb(nfft=512, nmel=26, fs=_ML_FS):
    def h2m(f): return 2595 * np.log10(1 + f / 700)
    def m2h(m): return 700 * (10 ** (m / 2595) - 1)
    pts = m2h(np.linspace(h2m(0), h2m(fs / 2), nmel + 2))
    b = np.floor((nfft + 1) * pts / fs).astype(int)
    fb = np.zeros((nmel, nfft // 2 + 1))
    for m in range(1, nmel + 1):
        l, c, r = b[m - 1], b[m], b[m + 1]
        for k in range(l, c): fb[m - 1, k] = (k - l) / (c - l + 1e-9)
        for k in range(c, r): fb[m - 1, k] = (r - k) / (r - c + 1e-9)
    return fb


def _mfcc(x16):
    global _FB
    if _FB is None: _FB = _melfb()
    win, hop = 512, 256; w = np.hanning(win); frames = []
    for s in range(0, len(x16) - win, hop):
        sp = np.abs(np.fft.rfft((x16[s:s+win] - x16[s:s+win].mean()) * w)) ** 2
        frames.append(np.fft.rfft(np.log(_FB @ sp + 1e-9)).real[:13])
    if not frames: return None
    frames = np.array(frames)
    return np.concatenate([frames.mean(0), frames.std(0)])


def drone_probability(block, fs_in=44100):
    """Return P(drone) in [0,1] for an audio block, or None if unusable."""
    try:
        x = block[:, 0] if getattr(block, "ndim", 1) > 1 else block
        x = np.asarray(x, dtype=np.float32)
        if fs_in != _ML_FS:
            n2 = max(512, int(len(x) * _ML_FS / fs_in))
            x = np.interp(np.linspace(0, len(x) - 1, n2), np.arange(len(x)), x)
        ft = _mfcc(x)
        if ft is None or not np.all(np.isfinite(ft)): return None
        z = (ft - _MEAN) / _SCALE
        h = np.maximum(0, z @ _W1 + _B1)
        o = h @ _W2 + _B2
        return float(1 / (1 + np.exp(-o[0])))
    except Exception as ex:
        # Surface the failure once instead of silently returning None forever
        # (a feature-pipeline bug would otherwise make ML quietly do nothing).
        global _WARNED
        if not _WARNED:
            print(f"[echo_ml] inference error (ML disabled for this run): {type(ex).__name__}: {ex}")
            _WARNED = True
        return None


_WARNED = False
